    def __getattr__(self, item):
        print(f"C.__getattr__ called for {item}")
        raise AttributeError(f"C has no attribute {item}")

@attr.s(slots=True)
class D(C):
    pass

d = D()
try:
    print(d.non_existent)
except AttributeError as e:
    print(f"Caught expected AttributeError: {e}")
