import attr
from functools import cached_property

class A:
    def __getattribute__(self, name):
        if name == "special":
            return "special_value"
        # We want to see if __getattr__ is called when this raises AttributeError
        # But __getattr__ is only called if __getattribute__ raises AttributeError.
        # The issue is that the generated __getattr__ might be swallowing or 
        # changing the AttributeError.
        try:
            return super().__getattribute__(name)
        except AttributeError:
            # If we raise a custom AttributeError here, does it propagate?
            raise AttributeError("Custom Error from __getattribute__")

@attr.s(slots=True)
class B(A):
    @cached_property
    def prop(self):
        return 42

b = B()
try:
    print(b.non_existent)
except AttributeError as e:
    print(f"Caught: {e}")
EOF
